mapper.select:
select * from ww_sys_log
where 1=1

	and instr(MOD_NAME,#{lModName}) > 0


	and OPT_DATE >= #{optDateStart}


	 and OPT_DATE <= #{optDateEnd} 


	and instr(OPT_NAME,#{lOptName}) > 0


	and instr(USER_ID,#{lUserId}) > 0


	and OPT_RST = #{optRst}


	and ID = #{id}

order by opt_date desc
